def get_bounding_box_for_color(grid, color):
    positions = []
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == color:
                positions.append((r, c))
    if not positions:
        return None
    r0 = min(p[0] for p in positions)
    r1 = max(p[0] for p in positions)
    c0 = min(p[1] for p in positions)
    c1 = max(p[1] for p in positions)
    return (r0, r1, c0, c1)

def extract_shape(grid, color):
    r0, r1, c0, c1 = get_bounding_box_for_color(grid, color)
    if r0 is None:
        return None
    # Extract the subgrid from r0..r1 and c0..c1
    return [[grid[r][c] for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

def transform(grid):
    # Find all colors
    colors = set()
    for row in grid:
        for cell in row:
            if cell != 0:
                colors.add(cell)

    # For each color, extract its shape
    shapes = {}
    for color in colors:
        shapes[color] = extract_shape(grid, color)

    # Now we have all shapes. Among same-color shapes, we need to... 
    # wait, in this test there's only one shape per color
    # Let's just extract and arrange them horizontally in sorted color order

    # Sort colors and extract shapes
    sorted_colors = sorted(colors)

    # For each shape, find its row span to determine the max height and where to place it
    max_span = 0
    for color in sorted_colors:
        shape = shapes[color]
        h = len(shape)
        w = len(shape[0]) if shape else 0
        if h > max_span:
            max_span = h

    # Build output grid filled with 0s
    output = [[0 for _ in range(max_span * len(sorted_colors))] for _ in range(max_span)]

    # Place shapes side by side
    col_offset = 0
    for col_idx, color in enumerate(sorted_colors):
        shape = shapes[color]
        # Center vertically in the output
        h = len(shape)
        v_off = (max_span - h) // 2

        start_col = col_offset
        for r in range(h):
            for c in range(len(shape[r])):
                output[r + v_off][start_col + c] = shape[r][c]

        col_offset += len(shape[0])  # Add width after each shape

